def ast_info(code):
    try:
        tree = ast.parse(code)
        types = [type(n).__name__ for n in ast.walk(tree)]
        return Counter(types), len(types)
    except Exception:
        return Counter(), 0

def get_literals(code):
    try:
        tree = ast.parse(code)
        strs = [n.value for n in ast.walk(tree) if isinstance(n, ast.Constant) and isinstance(n.value, str)]
