            jacc(fn1,fn2), jacc(at1,at2),
            litseq, numseq,
        ]
        # presence indicators for structural keywords (both / either)
        for kw_ in PRESENCE_KWS:
            in1 = kw_ in k1; in2 = kw_ in k2
            feat.append(float(in1 and in2))
            feat.append(float(in1 or in2))
        features.append(feat)
    return np.array(features)

