import ast
import difflib
import json
import keyword
import pickle
import re
from collections import Counter

import numpy as np
import pandas as pd
from sklearn.linear_model import Ridge
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler

KEYWORDS = set(keyword.kwlist)
BUILTINS = frozenset(dir(__builtins__))
N_FEATURES = 40


def _tokenize(code):
    return re.findall(r'\w+', code.lower())


def _char_ngrams(s, n):
    s = re.sub(r'\s+', ' ', s.lower())
    if len(s) < n:
        return {s} if s else set()
    return {s[i:i + n] for i in range(len(s) - n + 1)}


def _op_tokens(code):
    return re.findall(r'[+\-*/%=<>!&|^~]+|[:.,;()\[\]{}]', code)


def _ast_info(code):
    try:
        tree = ast.parse(code)
        types = [type(n).__name__ for n in ast.walk(tree)]
        return Counter(types), len(types)
    except Exception:
        return Counter(), 0


def _literals(code):
    try:
        tree = ast.parse(code)
        strs = [n.value for n in ast.walk(tree)
                if isinstance(n, ast.Constant) and isinstance(n.value, str)]
        nums = [str(n.value) for n in ast.walk(tree)
                if isinstance(n, ast.Constant) and isinstance(n.value, (int, float))]
        return strs, nums
    except Exception:
        return [], []


def _names(code):
    try:
        tree = ast.parse(code)
        funcs = {n.name for n in ast.walk(tree)
                 if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))}
        attrs = {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
        return funcs, attrs
    except Exception:
        return set(), set()


def _jaccard(a, b):
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)


def _dice(a, b):
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    return 2 * len(a & b) / (len(a) + len(b))


def _overlap(a, b):
    if not a or not b:
        return 0.0
    return len(a & b) / min(len(a), len(b))


def _cosine_counter(c1, c2):
    if not c1 or not c2:
        return 0.0
    keys = set(c1) | set(c2)
    dot = sum(c1[k] * c2[k] for k in keys)
    n1 = sum(v * v for v in c1.values()) ** 0.5
    n2 = sum(v * v for v in c2.values()) ** 0.5
    if n1 == 0 or n2 == 0:
        return 0.0
    return dot / (n1 * n2)


def _line_alignment(lines_a, lines_b):
    if not lines_a or not lines_b:
        return 0.0
    total = 0.0
    for x in lines_a:
        total += max(difflib.SequenceMatcher(None, x, y).ratio() for y in lines_b)
    return total / len(lines_a)


def extract_code_features(code_pairs):
    """Extract similarity features for pairs of code snippets.

    Each pair yields size/shape features, lexical overlap, character
    n-gram overlap, keyword/operator agreement, sequence alignment
    scores, AST structural similarity, identifier/name agreement,
    literal similarity, and a class-boilerplate agreement flag.
    Returns a numpy array with shape (n_samples, 40).
    """
    code_pairs = list(code_pairs)
    if not code_pairs:
        return np.zeros((0, N_FEATURES))
    features = []
    for code1, code2 in code_pairs:
        t1 = _tokenize(code1)
        t2 = _tokenize(code2)
        s1, s2 = set(t1), set(t2)
        c1, c2 = Counter(t1), Counter(t2)
        bi1, bi2 = _char_ngrams(code1, 2), _char_ngrams(code2, 2)
        tri1, tri2 = _char_ngrams(code1, 3), _char_ngrams(code2, 3)
        four1, four2 = _char_ngrams(code1, 4), _char_ngrams(code2, 4)
        k1 = s1 & KEYWORDS
        k2 = s2 & KEYWORDS
        o1, o2 = set(_op_tokens(code1)), set(_op_tokens(code2))
        oc1, oc2 = Counter(_op_tokens(code1)), Counter(_op_tokens(code2))
        lines1 = [l.strip() for l in code1.splitlines() if l.strip()]
        lines2 = [l.strip() for l in code2.splitlines() if l.strip()]
        a1, n1n = _ast_info(code1)
        a2, n2n = _ast_info(code2)
        seq = difflib.SequenceMatcher(None, code1, code2).ratio()
        seq_tok = difflib.SequenceMatcher(None, ' '.join(t1), ' '.join(t2)).ratio()
        seq_lines = difflib.SequenceMatcher(None, lines1, lines2).ratio()
        al12 = _line_alignment(lines1, lines2)
        al21 = _line_alignment(lines2, lines1)
        id1 = {w for w in s1 if w not in KEYWORDS and w not in BUILTINS}
        id2 = {w for w in s2 if w not in KEYWORDS and w not in BUILTINS}
        fn1, at1 = _names(code1)
        fn2, at2 = _names(code2)
        lit1, num1 = _literals(code1)
        lit2, num2 = _literals(code2)
        if lit1 or lit2:
            litseq = difflib.SequenceMatcher(None, ' '.join(lit1), ' '.join(lit2)).ratio()
        else:
            litseq = 1.0
        if num1 or num2:
            numseq = difflib.SequenceMatcher(None, ' '.join(num1), ' '.join(num2)).ratio()
        else:
            numseq = 1.0
        len1, len2 = len(code1), len(code2)
        tl1, tl2 = len(t1), len(t2)
        feat = [
            len1, len2, abs(len1 - len2), min(len1, len2) / max(len1, len2, 1),
            tl1, tl2, abs(tl1 - tl2), min(tl1, tl2) / max(tl1, tl2, 1),
            len(lines1), len(lines2), abs(len(lines1) - len(lines2)),
            _jaccard(s1, s2), _dice(s1, s2), _overlap(s1, s2),
            _cosine_counter(c1, c2),
            _jaccard(bi1, bi2), _jaccard(tri1, tri2), _jaccard(four1, four2),
            _dice(bi1, bi2), _dice(tri1, tri2),
            float(len(k1 & k2)), _jaccard(k1, k2),
            _jaccard(o1, o2), _cosine_counter(oc1, oc2),
            seq, seq_tok, seq_lines, (al12 + al21) / 2, min(al12, al21),
            _cosine_counter(a1, a2), _jaccard(set(a1), set(a2)),
            abs(n1n - n2n), min(n1n, n2n) / max(max(n1n, n2n), 1),
            _jaccard(id1, id2), _overlap(id1, id2),
            _jaccard(fn1, fn2), _jaccard(at1, at2),
            litseq, numseq,
            float('class' in k1 and 'class' in k2),
        ]
        features.append(feat)
    return np.array(features)


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--train_path', type=str, required=True)
    parser.add_argument('--split_path', type=str, required=True)
    args = parser.parse_args()

    df = pd.read_csv(args.train_path)
    with open(args.split_path, 'r') as f:
        split = json.load(f)

    train_idx = split['train']
    train_df = df.iloc[train_idx]

    train_pairs = list(zip(train_df['code1'], train_df['code2']))
    X_train = extract_code_features(train_pairs)
    y_train = train_df['similarity_score'].values

    model = make_pipeline(StandardScaler(), Ridge())
    model.fit(X_train, y_train)

    with open('/app/code_similarity_model.pkl', 'wb') as f:
        pickle.dump(model, f)
